p='Support/ErrorReport.cpp'
s=open(p).read()
s=s.replace('#include <wx/utils.h>\n','#include <wx/thread.h>\n#include <wx/utils.h>\n',1)
a='''void report_unexpected_error(std::string doing, std::string error, std::string where)
{
'''
b='''void report_unexpected_error(std::string doing, std::string error, std::string where)
{
    // An entry point on another thread (an HTTP callback, a worker) reports
    // on the main thread, where the waiting reports and the dialog live.
    if (!wxThread::IsMain()) {
        wxGetApp().CallAfter([doing = std::move(doing), error = std::move(error), where = std::move(where)]() mutable {
            report_unexpected_error(std::move(doing), std::move(error), std::move(where));
        });
        return;
    }
'''
assert a in s; s=s.replace(a,b)
open(p,'w').write(s)
p='Support/ErrorReport.hpp'
s=open(p).read()
a='''// The top handlers today: the Agent and Home pages' message handlers
// (AgentWebView, HomeWebView), the file picker's callback, which reads the
// chosen files after the page's message was handled (AgentWebView), the
// pumps that read an AI reply or title and a key check (AgentHost::pump_stream,
// AgentHost::pump_setup, reporting through the handler AgentWebView gives
// them), and the pages' own top level, which sends a report_error message
// (WebShared/bridgeClient.ts). An exception that leaves any other native
// event is OrcaSlicer's to handle, exactly as upstream handles it
// (GUI_App::OnExceptionInMainLoop).

#include <string>
'''
b='''// The top handlers today: the Agent and Home pages' message handlers
// (AgentWebView, HomeWebView), the pumps that read an AI reply or title and a
// key check (AgentHost::pump_stream, AgentHost::pump_setup, reporting through
// the handler AgentWebView gives them), every place JusPrin's own code starts
// running by itself -- a CallAfter, a timer, an HTTP callback, a thread --
// through reported() below, and the pages' own top level, which sends a
// report_error message (WebShared/bridgeClient.ts). An exception that leaves
// any other native event is OrcaSlicer's to handle, exactly as upstream
// handles it (GUI_App::OnExceptionInMainLoop).

#include <string>
#include <utility>
'''
assert a in s; s=s.replace(a,b)
a='''// The exception being handled, as a report names it: its type and what().
// Call inside a catch block.
std::string describe_current_exception();
'''
b=a+'''
// The top handler of an entry point JusPrin's own code starts: wraps the
// body of a CallAfter, a timer, an HTTP callback or a thread, so that an
// exception leaving it is reported, saying the app was `doing` this. Any
// thread.
template<class Body> auto reported(const char* doing, Body body)
{
    return [doing, body = std::move(body)](auto&&... arguments) mutable {
        try {
            body(std::forward<decltype(arguments)>(arguments)...);
        } catch (...) {
            report_unexpected_error(doing, describe_current_exception());
        }
    };
}
'''
assert a in s; s=s.replace(a,b)
open(p,'w').write(s)
EOF
