    bool        set_viewed_conversation(const std::string& conversation_id);
    // What only a checkpoint can hold: the model version the chat was left
    // on, the conversation item it was left after, when, and the card's
    // summary of that moment. The chat's intent and plan stay on the chat,
    // which nothing edits while it is inactive. A missing checkpoint means
    // the chat was left with no model version to bind it to.
    std::optional<nlohmann::json> chat_checkpoint(const std::string& conversation_id) const;
    void save_chat_checkpoint(const std::string& conversation_id, const std::string& version_id,
                              const nlohmann::json& summary, const std::string& timestamp);
    bool        needs_conversation_title(const std::string& conversation_id) const;
    bool        rename_conversation(const std::string& conversation_id, const std::string& title, bool generated = false);
    // The agent's restatement of what this chat asked the setup to be, in the
{
    ProjectStateDocument document;
    document.initialize_identity("p", "l", kT);
    const std::string first = document.active_conversation_id();
    REQUIRE(document.save_chat_checkpoint(first, "v-1", nlohmann::json{{"estimate", "saved"}}, kT));
    const auto saved = document.chat_checkpoint(first);
    REQUIRE(saved);
    CHECK((*saved)["versionId"] == "v-1");
    // The checkpoint holds what only it can; the chat keeps its intent and plan.
    CHECK_FALSE(saved->contains("planning"));

    const std::string second = document.create_conversation("Strong print", kT);
    REQUIRE(document.set_viewed_conversation(first));
    CHECK(document.active_conversation_id() == second);
    CHECK(document.viewed_conversation_id() == first);
    CHECK_FALSE(document.save_chat_checkpoint(first, "v-2", nlohmann::json::object(), kT));

    ProjectStateDocument reloaded;
    REQUIRE(reloaded.load(document.dump()) == ProjectStateDocument::LoadResult::Loaded);

