void OrcaHomeBackend::open_file()
{
    wxArrayString files;
    if (m_choose_files)
        files = m_choose_files();
    else
        wxGetApp().import_model(&m_frame, files);
    // Opened as a file opened from Finder or Explorer is, in a new project,
