#include <wx/uri.h>
#include <wx/webview.h>

#include <algorithm>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

namespace {

// How long a page may take to load before the window says it did not. A
// printer on the local network answers within seconds; WebKit's own limit,
// over a minute, is far longer than anyone watches a white window.
constexpr int kLoadDeadlineMs = 20000;

// PrusaLink and PrusaConnect pages sign in with the saved API REDACTED, as
// MainFrame::load_printer_url passes it to the Device tab.
wxString page_api_REDACTED(const DynamicPrintConfig& config)
{
    const auto* type = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
    if (type == nullptr || !config.has("printhost_apiREDACTED") || (type->value != htPrusaLink && type->value != htPrusaConnect))
        return {};
    return wxString::FromUTF8(config.opt_string("printhost_apiREDACTED"));
}

// "192.168.1.42:7125" for "REDACTED": where the
// window looked, without the scheme, a path, or any credentials.
std::string page_address(const std::string& url)
{
    const wxURI uri(wxString::FromUTF8(url));
    wxString    address = uri.GetServer();
    if (uri.HasPort())
        address += ":" + uri.GetPort();
    return address.empty() ? url : std::string(address.ToUTF8());
}

} // namespace

std::string PrinterWindow::page_url(const DynamicPrintConfig& config)
{
    // get_print_host_webui takes a mutable config; it only reads it.
    DynamicPrintConfig copy = config;
    return PrintHost::get_print_host_webui(&copy);
}

PrinterWindow::PrinterWindow(const std::string& printer_name, const DynamicPrintConfig& config)
    : PopOutWindow(wxString::FromUTF8(printer_name))
    , m_load_deadline(this)
}

void PrinterWebView::create_browser()
{
    m_browser = WebView::CreateWebView(this, "");
    add_page_strings(m_browser);

#ifdef __linux__
    inject_vue_resize_workaround(m_browser);

    auto cookiesPath = boost::filesystem::path(data_dir() + "/cache/cookies.db");
    auto wv = static_cast<WebKitWebView*>(m_browser->GetNativeBackend());
    auto wv_ctx = webkit_web_view_get_context(wv);
    auto cookieManager = webkit_web_context_get_cookie_manager(wv_ctx);
    webkit_cookie_manager_set_persistent_storage(cookieManager, cookiesPath.c_str(), WEBKIT_COOKIE_PERSISTENT_STORAGE_SQLITE);
#endif

    m_browser->Bind(wxEVT_WEBVIEW_ERROR, &PrinterWebView::OnError, this);
    m_browser->Bind(wxEVT_WEBVIEW_LOADED, &PrinterWebView::OnLoaded, this);
    m_browser->Bind(wxEVT_WEBVIEW_NEWWINDOW, &PrinterWebView::OnNewWindow, this);
    m_browser->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, &PrinterWebView::OnScriptMessage, this);
    update_mode();
}

void PrinterWebView::reset_browser()
{
    m_browser->Destroy(); // also removes it from the sizer
    create_browser();
    GetSizer()->Add(m_browser, wxSizerFlags().Expand().Proportion(1));
    Layout();

    // OnLoaded may have cleared m_url_deferred already, so requeue the last url for Show().
    m_apiREDACTED_sent  = false;
    m_url_loaded   = false;
    m_url_deferred = m_url;
}

// Same lookup as create_printer_webview_handler().
static PrintHostType active_host_type()
{
    if (wxGetApp().preset_bundle == nullptr)
        return htOctoPrint;
    return wxGetApp().preset_bundle->printers.get_edited_preset().config.option<ConfigOptionEnum<PrintHostType>>("host_type")->value;
}

void PrinterWebView::load_url(wxString& url, wxString apiREDACTED)
{
//    this->Show();
//    this->Raise();
    const PrintHostType host_type = active_host_type();
    // Selecting the tab requests the same page again; navigating would reload it and drop its state.
    if (m_url_loaded && url == m_url && apiREDACTED == m_apiREDACTED && host_type == m_host_type)
        return;

    m_url = url;
    m_apiREDACTED = apiREDACTED;
    m_host_type = host_type;
    m_apiREDACTED_sent = false;
    m_url_loaded = false;
    m_handler = create_printer_webview_handler(*this);

    if (this->IsShown()) {
        //ORCA: m_url_deferred will be cleared on load success
        //m_url_deferred.clear();
        m_browser->LoadURL(url);
    } else {
        m_url_deferred = url;
    }
    //m_browser->SetFocus();
    UpdateState();
}

bool PrinterWebView::Show(bool show)
{
    if (show && std::exchange(m_reset_on_show, false))
        reset_browser();
    if (show && !m_url_deferred.empty()) {
        m_browser->LoadURL(m_url_deferred);
        //ORCA: m_url_deferred will be cleared on load success
        //m_url_deferred.clear();
    }
    return wxPanel::Show(show);
}

void PrinterWebView::reload()
{
    m_browser->Reload();
}

void PrinterWebView::update_mode()
{
    m_browser->EnableAccessToDevTools(wxGetApp().app_config->get_bool("developer_mode"));
}

/**
 * Method that retrieves the current state from the web control and updates the
 * GUI the reflect this current state.
 */
void PrinterWebView::UpdateState() {
  // SetTitle(m_browser->GetCurrentTitle());

}

void PrinterWebView::OnClose(wxCloseEvent& evt)
{
    this->Hide();
}

