  lastOfType(type: string): Envelope | undefined {
    return [...this.received].reverse().find((e) => e.type === type);
  }

  ofType(type: string): Envelope[] {
    return this.received.filter((e) => e.type === type);
  }

  messages(): Envelope[] {
    return this.received;
  }

  clear(): void {
    this.received = [];
  }
