export const initialState: HomeState = {
  connection: 'connecting',
  loaded: false,
  appearance: 'light',
  projects: [],
  printers: [],
  screen: { kind: 'home' },
  stateCount: 0,
};

export type HomeAction =
  | { kind: 'connection'; state: ConnectionState; detail?: string }
  | { kind: 'envelope'; envelope: Envelope }
  | { kind: 'printer_action' }
  | { kind: 'confirmation_answered' }
  | { kind: 'show'; screen: Screen }
  | { kind: 'report_form_reset' }
  | { kind: 'report_sending' }
  | { kind: 'onboarding_action' }
  | { kind: 'agent_setup_hidden' };

export function reduce(state: HomeState, action: HomeAction): HomeState {
  if (action.kind === 'connection') {
    return { ...state, connection: action.state, connectionDetail: action.detail };
  }
  if (action.kind === 'printer_action') {
    return { ...state, printerError: undefined };
  }
  if (action.kind === 'confirmation_answered') {
    return { ...state, confirmation: undefined };
  }
  if (action.kind === 'show') {
    return { ...state, screen: action.screen };
  }
  if (action.kind === 'report_form_reset') {
    return { ...state, reportPhoto: undefined, reportResult: undefined };
  }
  if (action.kind === 'report_sending') {
    return { ...state, reportResult: undefined };
  }
  if (action.kind === 'onboarding_action') {
    return { ...state, onboardingError: undefined };
  }
  if (action.kind === 'agent_setup_hidden') {
    return { ...state, agentSetupHidden: true };
  }
  const { type, payload } = action.envelope;
  switch (type) {
    case 'state': {
      const next = payload as StatePayload;
      return {
        ...state,
        loaded: true,
        appearance: next.appearance,
        projects: next.projects ?? [],
        projectsProblem: next.projectsProblem || undefined,
        printers: next.printers ?? [],
        error: undefined,
        highlightPrinter: next.highlightPrinter || undefined,
        stateCount: state.stateCount + 1,
        onboarding: next.onboarding,
      };
    }
    case 'screen': {
      const asked = payload as ScreenPayload;
      return {
        ...state,
        // The host asks for a screen each time Home comes back on screen.
        agentSetupHidden: undefined,
        screen:
          asked.screen === 'history'
            ? { kind: 'history', back: asked.back, projectId: asked.projectId, focus: asked.focus }
            : { kind: 'home' },
      };
    }
    case 'history':
      return {
        ...state,
        history: (payload as HistoryPayload).entries ?? [],
        reportsOffered: (payload as HistoryPayload).reportsOffered,
      };
    case 'print_report_photo':
      // Cancelling the file dialog keeps the photo already there.
      return { ...state, reportPhoto: (payload as { photo?: PrintReportPhoto }).photo ?? state.reportPhoto };
    case 'print_report_result':
      return { ...state, reportResult: payload as PrintReportResult };
    case 'projects':
      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
    case 'printers':
      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
    case 'appearance':
      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
    case 'printer_error':
      return { ...state, printerError: payload as PrinterErrorPayload };
      onExport: (entry: HistoryEntry, beside?: string) =>
        client.send('export_gcode', { projectId: entry.projectId, hash: entry.hash, ...(beside ? { beside } : {}) }),
      onReport: (entry: HistoryEntry) => {
        dispatch({ kind: 'report_form_reset' });
        setReporting(entry.hash);
      },
    };
    const reportedEntry = state.history?.find((entry) => entry.hash === reporting);
    return (
      <>
        <PrintHistory key={screenKey(screen)} screen={screen} entries={state.history} problem={state.projectsProblem} printers={state.printers}
          reportsOffered={Boolean(state.reportsOffered)} actions={actions} />
        {reportedEntry && (
          <PrintReportForm
            entry={reportedEntry}
            photo={state.reportPhoto}
            result={state.reportResult?.hash === reportedEntry.hash ? state.reportResult : undefined}
            onChoosePhoto={() => client.send('print_report_choose_photo', {})}
            onRemovePhoto={() => dispatch({ kind: 'report_form_reset' })}
            onSend={(form) => {
              dispatch({ kind: 'report_sending' });
              client.send('print_report_send', { projectId: reportedEntry.projectId, hash: reportedEntry.hash, ...form });
            }}
            onClose={() => setReporting(undefined)}
            onGetNewVersion={() => client.send('check_for_updates', {})}
          />
        )}
      </>
    );
  }

  // The whole page takes a dropped file, which opens as a new project. The
  // page sees a file's name and bytes, not where it came from. On macOS the
  // page never sees the drag; the app opens the file from its own folder
  // (HomeWebView.cpp).
  const openDropped = (event: DragEvent) => {
    const files = Array.from(event.dataTransfer.files ?? []);
    event.preventDefault();
    if (files.length === 0) return;
    Promise.all(files.map((file) => readAsDataUrl(file).then((dataBase64) => ({ name: file.name, dataBase64 }))))
      .then((read) => client.send('open_dropped_files', { files: read }))

