  window.fake = {
    deliver(type, payload) { window.__jusprinBridge.deliver({ ...P, id: 'h-' + (n++), type, payload }); },
  };
  window.wx = { postMessage(json) {
    const m = JSON.parse(json); window.sent.push(m);
    if (m.type === 'hello') setTimeout(() => { window.fake.deliver('hello_ack', { protocolVersion: 1 }); if (window.onHello) window.onHello(); }, 0);
  } };
})();
