  // A JusPrin the server still serves: checks for the new version at once
  // and opens Preferences › Updates.
  getNewVersion: () => void;
}

// The page's own button classes: the Home page and the Agent page each draw
// the design system's buttons with their own.
export interface SignInButtons {
  primary: string;
  secondary: string;
}

export interface SignInDoorProps {
  phase: SignInPhase;
  email: SignInEmailStep | null | undefined;
  // Why the last sign-in did not finish, already worded.
  error?: string;
  // The error is the server refusing this release of JusPrin: signing in
  // again would fail the same way, so the door offers the new version.
  outdated?: boolean;
  actions: SignInActions;
  buttons: SignInButtons;
  // What the screen says above the door while nothing has started, such as
  // the sign-up offer.
  children?: ReactNode;
}

// What the server's refusal means to the person.
function refusalText(email: SignInEmailStep): string {
  switch (email.refusal) {
    case 'wrong_code':
      return t`That code is wrong.`;
    case 'expired_code':
      return t`That code no longer works. We can send a new one.`;
    case 'too_many_tries':
      return t`Too many tries. Wait a few minutes, or email me a code.`;
    case 'too_many_codes':
      return t`Too many codes were sent to this address. Try again in an hour.`;
    case 'wrong_password':
      return t`That password is wrong.`;
    default:
      return '';
  }
}

// Links in a row, separated by middle dots, with Cancel apart on the right.
function LinkRow({ links, cancel }: { links: [string, () => void][]; cancel?: () => void }) {
  return (
    <div className="sign-in-link-row">
      <span className="sign-in-links">
        {links.map(([label, onClick], index) => (
          <span key={label}>
            {index > 0 && <span className="sign-in-link-dot" aria-hidden="true">·</span>}
            <button type="button" className="sign-in-link" onClick={onClick}>{label}</button>
          </span>
        ))}
      </span>
      {cancel && <button type="button" className="sign-in-link" onClick={cancel}>{t`Cancel`}</button>}
    </div>
  );
}

// The code step (boards first-run-14 to 16).
function CodeStep({ email, actions, buttons, onChangeEmail, onBrowser }: {
  email: SignInEmailStep; actions: SignInActions; buttons: SignInButtons; onChangeEmail: () => void; onBrowser: () => void;
}) {
  const [code, setCode] = useState('');
  const field = useRef<HTMLInputElement>(null);
  const refusal = refusalText(email);
  // A code that can no longer work: the way on is a new one.
  const spent = email.refusal === 'expired_code';
  const address = email.email;
  // A new code empties the cells; so does typing after a wrong one.
  useEffect(() => {
    if (email.codeResent) setCode('');
  }, [email.codeResent]);
  useEffect(() => {
    if (email.refusal === 'wrong_code' && !email.busy) setCode('');
  }, [email.refusal, email.busy]);
  useEffect(() => {
    if (!email.busy) field.current?.focus();
  }, [email.busy]);
  return (
    <>
      <p className="sign-in-title">{t`Check your email.`}</p>
      <p className="sign-in-detail">
        {email.codeResent ? t`We sent a new code to ${address}.` : t`We sent a 6-digit code to ${address}.`}
      </p>
      <CodeField
        ref={field}

// The email sign-in, while the phase is Email.
struct CloudEmailStep
{
    // Choose: the person picks a code or types the password. Code: a code
    // was sent and the app waits for it.
    enum class Step { Choose, Code };
    Step        step{Step::Choose};
    std::string email;
    // A code, a password or a request for a code is with the server.
    bool        busy{false};
    // The server's refusal of the last try: "wrong_code", "expired_code"
    // (the code no longer works: it expired or was tried too often),
    // "too_many_codes", "wrong_password" or "too_many_tries" (passwords).
    // Empty when there is none.
    std::string refusal;
    // A new code went out because the person asked for one.
    bool        code_resent{false};

    bool operator==(const CloudEmailStep& other) const
    {
        return step == other.step && email == other.email && busy == other.busy && refusal == other.refusal &&
               code_resent == other.code_resent;
    }
    bool operator!=(const CloudEmailStep& other) const { return !(*this == other); }
};

struct CloudSignInOutcome
{
    enum class Kind { SignedIn, Expired, Failed };
    Kind            kind{Kind::Failed};

