    expect(screen.getByRole('button', { name: 'Use a password instead' })).toBeInTheDocument();
    await userEvent.click(screen.getByRole('button', { name: 'Cancel' }));
    expect(host.lastOfType('onboarding_sign_in_cancel')).toBeDefined();
  });

