async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  await wait(300);
  const onboarding = (o) => ({ visible: true, step: 'welcome', printersScreen: 'add_printer', signIn: 'idle', email: null, signInError: '', accountEmail: '', agentConfigured: false, agentKeyProvider: '', printerImport: { app: '', source: '', printers: [], selected: '', filamentCount: 0, settingsCount: 0, result: null }, wayProblem: '', printerForm: null, agentCard: 'none', ...o });
  const state = (o) => ({ appearance: 'light', projects: [], printers: [], onboarding: onboarding(o) });
  fake.deliver('state', state({}));
  await wait(200);
  const input = document.querySelector('input[type=email]');
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
  setter.call(input, 'alex@gmail'); input.dispatchEvent(new Event('input', { bubbles: true }));
  await wait(100);
  [...document.querySelectorAll('button')].find(b => b.textContent.trim() === 'Sign up free').click();
  await wait(100);
  fake.deliver('state', state({ signIn: 'email', email: { step: 'choose', email: 'alex@gmail', busy: false, refusal: 'incomplete_address', codeResent: false } }));
  await wait(300);
  return [window.sent.map(m => m.type).slice(-3), document.querySelector('[role=alert]')?.textContent];
}

