ShellController::ShellController()
{
    Bind(wxEVT_TIMER, reported("saving the project and running the app's timers", [this](wxTimerEvent&) {
        if (m_autosave) {
            m_autosave->tick();
            const std::string head = m_autosave->current_version();
            const auto document_revision = m_agent_pane ?
                m_agent_pane->web_view().host().persistence().document().doc_revision() : 0;
            if (!head.empty() && m_autosave->state() == Workspace::ProjectAutosave::State::Saved &&
                (head != m_timeline_version_head || document_revision != m_timeline_document_revision)) {
                if (m_agent_pane && m_agent_pane->web_view().host().checkpoint_active_chat()) {
                    m_timeline_version_head = m_autosave->current_version();
                    m_timeline_document_revision = m_agent_pane->web_view().host().persistence().document().doc_revision();
                    m_agent_pane->web_view().host().refresh_page_state();
                }
            }
            const std::string key = std::to_string(int(m_autosave->state())) + m_autosave->error();
            if (key != m_autosave_status_key && m_status_row != nullptr) {
                m_autosave_status_key = key;
                m_status_row->refresh();
                if (m_autosave->state() == Workspace::ProjectAutosave::State::Saved &&
                    m_home != nullptr && m_home->IsShownOnScreen())
                    m_home->refresh();
            }
        }
        if (m_status_row != nullptr && m_frame != nullptr) {
            const wxString title = m_status_row->project_summary().BeforeFirst('\n');
            if (m_frame->GetTitle() != title) {
                m_frame->SetTitle(title);
                m_frame->update_title_colour_after_set_title();
            }
        }
        if (m_left_pane != nullptr && m_plater != nullptr && m_plater->is_background_process_slicing())
            m_left_pane->refresh_slicing_progress();
        if (!m_agent_pane) return;
}

} // namespace

ProjectAutosave::ProjectAutosave(Plater& plater, Agent::ProjectPersistence& persistence, IWorkspace& workspace,
                                 std::filesystem::path root)
    : m_plater(plater), m_persistence(persistence), m_workspace(workspace), m_root(std::move(root)),
      m_next_probe(Clock::now()), m_last_edit(Clock::now()), m_last_semantic_edit(Clock::now())
{
    m_subscription = m_workspace.subscribe([this](const WorkspaceChanged& change) {
        if (!project_edit(change.reasons))
            return;
        ++m_event_sequence;
        m_last_edit = Clock::now();
        m_state = State::Saving;
    });
    adopt_project();
}

ProjectAutosave::~ProjectAutosave()
{
    m_subscription.reset();
    if (m_worker.valid())
        m_worker.wait();
}

std::string ProjectAutosave::project_name() const
{
    return m_project_name.empty() ? std::string(m_plater.get_project_name().ToUTF8()) : m_project_name;
}

void ProjectAutosave::fail(const std::string& message)
{
    BOOST_LOG_TRIVIAL(error) << "Local project save failed: " << message;
    m_error = message;
    m_state = State::Failed;
}

void ProjectAutosave::observe_document_change()
{
    const auto revision = m_persistence.document().doc_revision();
    if (revision == m_seen_semantic_revision)
        return;
    const auto now = Clock::now();
    m_seen_semantic_revision = revision;
    m_last_semantic_edit = now;
    if (!m_first_semantic_edit)
        m_first_semantic_edit = now;
    m_state = State::Saving;
}

std::string ProjectAutosave::observed_input() const
{
    // Only native printable project state belongs in checkpoint detection.
    // Conversation, plans, intent, audit, and print facts are durable in the
    // current document and cannot force a model export.
    // The scan touches identities, timestamps and small metadata, never mesh
    // triangles or Orca's 3MF writer.
    std::ostringstream out;
    out << std::setprecision(17) << m_event_sequence << ';';
    append_text(out, m_persistence.document().project_id());

