diff --git a/src/slic3r/GUI/JusPrin/Updates/LaunchRecord.cpp b/src/slic3r/GUI/JusPrin/Updates/LaunchRecord.cpp
new file mode 100644
index 0000000000..730ea52140
--- /dev/null
+++ b/src/slic3r/GUI/JusPrin/Updates/LaunchRecord.cpp
@@ -0,0 +1,50 @@
+#include "LaunchRecord.hpp"
+
+#include "libslic3r/AppConfig.hpp"
+
+#include <nlohmann/json.hpp>
+
+#include <algorithm>
+#include <cctype>
+#include <cstdint>
+#include <iomanip>
+#include <random>
+#include <sstream>
+
+namespace Slic3r::GUI::JusPrin::Updates {
+
+namespace {
+
+bool is_install_id(const std::string& value)
+{
+    return value.size() == kInstallIdLength &&
+           std::all_of(value.begin(), value.end(), [](unsigned char c) { return std::isdigit(c) || (c >= 'a' && c <= 'f'); });
+}
+
+std::string new_install_id()
+{
+    static std::mt19937_64                       engine(std::random_device{}());
+    std::uniform_int_distribution<std::uint64_t> distribution;
+    std::ostringstream                           out;
+    out << std::hex << std::setfill('0') << std::setw(16) << distribution(engine) << std::setw(16) << distribution(engine);
+    return out.str();
+}
+
+} // namespace
+
+std::string install_id(AppConfig& config)
+{
+    const std::string stored = config.get(kInstallIdKey);
+    if (is_install_id(stored))
+        return stored;
+    const std::string made = new_install_id();
+    config.set(kInstallIdKey, made);
+    return made;
+}
+
+std::string launch_report_body(const std::string& install_id, const std::string& app, const std::string& os)
+{
+    return nlohmann::json{{"install", install_id}, {"app", app}, {"os", os}}.dump();
+}
+
+} // namespace Slic3r::GUI::JusPrin::Updates
diff --git a/src/slic3r/GUI/JusPrin/Updates/LaunchReport.cpp b/src/slic3r/GUI/JusPrin/Updates/LaunchReport.cpp
new file mode 100644
index 0000000000..cfb2c75fdd
--- /dev/null
+++ b/src/slic3r/GUI/JusPrin/Updates/LaunchReport.cpp
@@ -0,0 +1,49 @@
+#include "LaunchReport.hpp"
+
+#include "LaunchRecord.hpp"
+#include "Version.hpp"
+
+#include "libslic3r/AppConfig.hpp"
+#include "slic3r/GUI/GUI_App.hpp"
+#include "slic3r/GUI/JusPrin/Agent/AgentConfiguration.hpp"
+#include "slic3r/Utils/Http.hpp"
+
+#include <boost/log/trivial.hpp>
+
+#include <wx/utils.h>
+
+#include <string>
+
+namespace Slic3r::GUI::JusPrin::Updates {
+
+void report_launch()
+{
+    // Recreating the GUI, for a language change, attaches the shell again;
+    // the run still started once.
+    static bool reported = false;
+    if (reported || wxGetApp().app_config == nullptr)
+        return;
+    reported = true;
+
+    AppConfig& config = *wxGetApp().app_config;
+    // The same stealth mode the update check reads: the person asked the app
+    // to make no calls of its own.
+    if (config.get_bool("stealth_mode"))
+        return;
+
+    const std::string body = launch_report_body(install_id(config), version_label(), std::string(wxGetOsDescription().ToUTF8()));
+    Http::post(Agent::cloud_launches_url(&config))
+        .header("Content-Type", "application/json")
+        .header("User-Agent", user_agent())
+        .set_post_body(body)
+        .timeout_connect(5)
+        .timeout_max(10)
+        .on_error([](std::string, std::string error, unsigned status) {
+            // A lost report is a count the server misses, nothing the person
+            // needs to hear about.
+            BOOST_LOG_TRIVIAL(info) << "JusPrin's start report was not delivered: HTTP " << status << ", " << error;
+        })
+        .perform();
+}
+
+} // namespace Slic3r::GUI::JusPrin::Updates

